import re

class Solution:
    def tidyPath(self, path: str) -> str:
        t = path + "/"
        rules = [(r"//+", "/"), (r"/\./", "/"), (r"/(?!\.\./)[^/]+/\.\./", "/"), (r"^/\.\./", "/")]
        changed = True
        while changed:
            changed = False
            for pattern, repl in rules:
                new = re.sub(pattern, repl, t, count=1)
                if new != t:
                    t, changed = new, True
        return t.rstrip("/") or "/"

