class Solution {
    public String tidyPath(String path) {
        String t = path + "/";
        String[][] rules = {{"//+", "/"}, {"/\\./", "/"}, {"/(?!\\.\\./)[^/]+/\\.\\./", "/"}, {"^/\\.\\./", "/"}};
        boolean changed = true;
        while (changed) {
            changed = false;
            for (String[] r : rules) {
                String next = t.replaceFirst(r[0], r[1]);
                if (!next.equals(t)) { t = next; changed = true; }
            }
        }
        while (t.length() > 1 && t.endsWith("/")) t = t.substring(0, t.length() - 1);
        return t;
    }
}

