class Solution {
    // One rewrite step on t (which always ends with '/'); returns true if something changed.
    bool rewrite(string& t) {
        int n = t.size();
        for (int i = 0; i + 1 < n; i++) {
            if (t[i] != '/') continue;
            int j = i + 1;
            while (j < n && t[j] != '/') j++;
            if (j == n) break;
            string part = t.substr(i + 1, j - i - 1);
            if (part.empty() || part == ".") { t.erase(i, j - i); return true; }
            if (part == "..") {
                int s = i - 1;
                while (s >= 0 && t[s] != '/') s--;
                if (s < 0) s = i;
                t.erase(s, j - s);
                return true;
            }
        }
        return false;
    }

public:
    string tidyPath(string& path) {
        string t = path + "/";
        while (rewrite(t)) {}
        while (t.size() > 1 && t.back() == '/') t.pop_back();
        return t;
    }
};

