// One rewrite step on t (which always ends with '/'); returns true if something changed.
static bool rewrite(char* t) {
    int n = strlen(t);
    for (int i = 0; i + 1 < n; i++) {
        if (t[i] != '/') continue;
        int j = i + 1;
        while (j < n && t[j] != '/') j++;
        int len = j - i - 1;
        if (j == n) break;
        if (len == 0 || (len == 1 && t[i + 1] == '.')) {
            memmove(t + i, t + j, n - j + 1);
            return true;
        }
        if (len == 2 && t[i + 1] == '.' && t[i + 2] == '.') {
            int s = i - 1;
            while (s >= 0 && t[s] != '/') s--;
            if (s < 0) s = i;
            memmove(t + s, t + j, n - j + 1);
            return true;
        }
    }
    return false;
}

char* tidyPath(char* path) {
    int n = strlen(path);
    char* t = malloc(n + 2);
    memcpy(t, path, n);
    t[n] = '/';
    t[n + 1] = '\0';
    while (rewrite(t)) {}
    int len = strlen(t);
    while (len > 1 && t[len - 1] == '/') t[--len] = '\0';
    return t;
}

