class Solution {
public:
    string tidyPath(string& path) {
        vector<string> stack;
        stringstream in(path);
        string part;
        while (getline(in, part, '/')) {
            if (part == "..") { if (!stack.empty()) stack.pop_back(); }
            else if (!part.empty() && part != ".") stack.push_back(part);
        }
        string out;
        for (auto& p : stack) out += "/" + p;
        return out.empty() ? "/" : out;
    }
};

