char* tidyPath(char* path) {
    int n = strlen(path), top = 0;
    int* start = malloc((n + 1) * sizeof(int));
    int* len = malloc((n + 1) * sizeof(int));
    for (int i = 0; i < n;) {
        while (i < n && path[i] == '/') i++;
        int j = i;
        while (j < n && path[j] != '/') j++;
        int L = j - i;
        if (L == 2 && path[i] == '.' && path[i + 1] == '.') { if (top > 0) top--; }
        else if (L > 0 && !(L == 1 && path[i] == '.')) { start[top] = i; len[top] = L; top++; }
        i = j;
    }
    char* out = malloc(n + 2);
    int w = 0;
    for (int k = 0; k < top; k++) {
        out[w++] = '/';
        memcpy(out + w, path + start[k], len[k]);
        w += len[k];
    }
    if (w == 0) out[w++] = '/';
    out[w] = '\0';
    free(start);
    free(len);
    return out;
}
